    static char[] s;
    static long n;
    static long len;

    static long check(long a) {
        for (long i = 1; i <= a - n; i++) {
            if (s[(int) (len - i)] != s[(int) (len - i - a)]) {
                return 0;
            }
        }
        return 1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        s = scanner.next().toCharArray();
        len = s.length;
        n = scanner.nextLong();

        long ans = 0;
        long temp = 0;
        long min;
        long max;

        if (n > len) {
            min = (len + n) / 2;
        } else {
            min = n;
        }

        max = (len + n) / 2;

        for (long i = 0; i < len; i++) {
            for (long j = 1; j * 2 + i <= len; j++) {
                long key = 1;
                for (long k = 1; k <= j; k++) {
                    if (s[(int) (i + k - 1)] != s[(int) (i + k + j - 1)]) {
                        key = 0;
                    }
                }
                if (key == 1 && j > temp) {
                    temp = j;
                }
            }
        }

        for (long i = max; i >= min && ans == 0; i--) {
            if (check(i) == 1) {
                ans = i;
            }
        }

        if (min > ans) {
            ans = min;
        }
        if (temp > ans) {
            ans = temp;
        }

        System.out.print(2 * ans);
    }
}

